// Command summarizer reads a GitLab project's activity over the last N days
// and writes two Markdown reports — one customer-facing, one team-facing —
// generated by an LLM. One project per run. Outputs land under a configurable
// directory. See .messages for the run summary written to stderr.
//
// Usage:
//
//	summarizer run --project group/subgroup/project --since 7d
//	summarizer run --project group/subgroup/project --since 7d --dry-run
//	summarizer --version
//	summarizer --help
//
// Env vars (do not store tokens in config files):
//
//	GITLAB_TOKEN       required for fetch
//	OPENAI_API_KEY     required when --provider openai (default) and baseURL is api.openai.com; optional otherwise
//	OPENAI_BASE_URL    overrides the OpenAI-compatible endpoint (Ollama, vLLM, LM Studio)
//	ANTHROPIC_API_KEY  required when --provider anthropic
package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"os"
	"os/signal"
	"slices"
	"strings"
	"syscall"
	"time"

	"github.com/inful/summarizer/internal/config"
	"github.com/inful/summarizer/internal/gitlab"
	"github.com/inful/summarizer/internal/llm"
	"github.com/inful/summarizer/internal/publisher"
	"github.com/inful/summarizer/internal/run"
	"github.com/inful/summarizer/internal/safety"
)

// Build-time variables, overridden via:
//
//	go build -ldflags "-X main.version=vX.Y.Z -X main.commit=$(git rev-parse HEAD) -X main.date=..."
//
// Default values are intentionally informational rather than empty
// so a developer running `go run` sees what they're running. Goreleaser
// injects the real values at release time (see .goreleaser.yaml).
var (
	version = "dev"
	commit  = "none"
	date    = "unknown"
)

func main() {
	if len(os.Args) < 2 {
		usage()
		os.Exit(2)
	}
	switch os.Args[1] {
	case "run":
		os.Exit(runCmd(os.Args[2:]))
	case "version", "--version", "-v":
		fmt.Printf("summarizer %s (commit %s, %s)\n", version, commit, date)
		os.Exit(0)
	case "help", "--help", "-h":
		usage()
		os.Exit(0)
	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n\n", os.Args[1])
		usage()
		os.Exit(2)
	}
}

func usage() {
	fmt.Fprint(os.Stderr, `summarizer — GitLab project activity → two Markdown reports

Commands:
  run         Fetch activity, call LLM, write reports
  version     Print version and exit
  help        Print this message

Run 'summarizer run --help' for run flags.
`)
}

// exit codes — distinct branches in a cron script can react to each.
const (
	exitOK        = 0
	exitUsage     = 2
	exitConfig    = 3
	exitGitLab    = 4
	exitLLM       = 5
	exitWrite     = 6
	exitEnv       = 7
	exitInjection = 8
	exitUnknown   = 1
)

func runCmd(args []string) int {
	var projects stringSliceFlag
	fs := flag.NewFlagSet("run", flag.ContinueOnError)
	fs.Usage = func() {
		fmt.Fprintf(os.Stderr, `summarizer run — fetch + summarize one or more GitLab projects

Flags:
`)
		fs.PrintDefaults()
		fmt.Fprintf(os.Stderr, `
Config (YAML file, default ./summarizer.yaml) and CLI flags both contribute;
CLI wins. See examples/summarizer.yaml.

Env:
  GITLAB_TOKEN       required
  OPENAI_API_KEY     required when --provider openai (default); optional if --openai-base-url points at a local server
  OPENAI_BASE_URL    overrides the OpenAI-compatible endpoint (Ollama, vLLM, LM Studio)
  ANTHROPIC_API_KEY  required when --provider anthropic
`)
	}

	var (
		since          = fs.Duration("since", 0, "rolling window: '168h' for 7d, '720h' for 30d. Default from config.")
		provider       = fs.String("provider", "", "LLM provider: openai or anthropic (default from config)")
		model          = fs.String("model", "", "LLM model id (default from config)")
		outputDir      = fs.String("output-dir", "", "output directory (default from config)")
		maxEvents      = fs.Int("max-events", 0, "hard cap on events sent to the LLM (default 200)")
		force          = fs.Bool("force", false, "overwrite existing output files")
		dryRun         = fs.Bool("dry-run", false, "fetch GitLab data and print a summary; no LLM call, no file write")
		includeDiffs   = fs.Bool("include-diffs", false, "fetch per-MR diff text and feed it into the team prompt so the model can reason about code changes (default off; adds one API call per MR)")
		safetyURL      = fs.String("safety-url", "", "decision API base URL for prompt-injection guard (default from config safety.decision_url)")
		safetyToken    = fs.String("safety-token", "", "decision API token (default from $SAFETY_DECISION_TOKEN env or config)")
		safetyEnabled  = fs.Bool("safety-enabled", false, "gate every LLM call through the prompt-injection detector; hard-fails the run on verdict (default off)")
		gitlabHost     = fs.String("gitlab-host", "", "GitLab base URL, e.g. https://gitlab.example.com (default from config)")
		gitlabToken    = fs.String("gitlab-token", "", "GitLab PRIVATE-TOKEN (default: $GITLAB_TOKEN). Prefer env var.")
		discoverGroups = stringSliceFlag{}
		internalOnly   = stringSliceFlag{}
		periodMode     = fs.String("period-mode", "", "Period bucket shape: 'daily' (default; each run gets its own <prefix>/<YYYY-MM-DD>/ directory) or 'monday' (bucket is the ISO week's Monday, so daily cron runs within Mon-Sun overwrite the same directory, branch and MR)")
		discoverTopic  = fs.Bool("discover-by-topic", false, "Scan every project on the GitLab instance carrying a summarize or summarize-team-only topic, across all groups the token can see. Same activity gate and audience policy as --discover-group; composes with it.")
		openaiKey      = fs.String("openai-key", "", "OpenAI API key (default: $OPENAI_API_KEY). Optional when --openai-base-url is set to a non-default host (e.g. local Ollama/vLLM/LM Studio).")
		openaiBaseURL  = fs.String("openai-base-url", "", "OpenAI-compatible base URL (default $OPENAI_BASE_URL, then config openai_base_url, then https://api.openai.com/v1). Set to a local server for Ollama/vLLM/LM Studio.")
		anthropicKey   = fs.String("anthropic-key", "", "Anthropic API key (default: $ANTHROPIC_API_KEY). Prefer env var.")
		configPath     = fs.String("config", "./summarizer.yaml", "path to YAML config file")
	)
	fs.Var(&projects, "project", "GitLab project path (repeatable, or comma-separated). Examples: --project group/a --project group/b, or --project group/a,group/b. Composes with --discover-group; an explicit listing takes precedence on duplicate paths.")
	fs.Var(&discoverGroups, "discover-group", "GitLab group path to scan for active projects (repeatable, or comma-separated). Each project's MRs in the window are probed; active ones join the run alongside any --project listings. Recursion into subgroups is not implemented in v1 — pass the leaf group you want covered.")
	fs.Var(&internalOnly, "internal-only-project", "Project path whose customer-facing output is suppressed (repeatable, or comma-separated). Same effect as setting the summarize-team-only GitLab topic on the project. The three sources (this flag, the YAML internal_only_projects: block, the GitLab topic) union together.")
	if err := fs.Parse(args); err != nil {
		return exitUsage
	}

	if len(projects) == 0 && len(discoverGroups) == 0 && !*discoverTopic {
		fmt.Fprintln(os.Stderr, "error: at least one --project, --discover-group or --discover-by-topic is required")
		return exitUsage
	}

	// Config: load YAML, then apply CLI overrides (CLI wins), then defaults.
	cfg, err := config.Load(*configPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "config error: %v\n", err)
		return exitConfig
	}
	if *gitlabHost != "" {
		cfg.GitLabHost = *gitlabHost
	}
	if *model != "" {
		cfg.Model = *model
	}
	if *openaiBaseURL != "" {
		cfg.OpenAIBaseURL = *openaiBaseURL
	} else if env := os.Getenv("OPENAI_BASE_URL"); env != "" {
		cfg.OpenAIBaseURL = env
	}
	if *outputDir != "" {
		cfg.OutputDir = *outputDir
	}
	if *since > 0 {
		// Encode the CLI window as a Go duration string in DefaultLookback
		// so the rest of the config code path treats it uniformly.
		cfg.DefaultLookback = since.String()
	}
	if *maxEvents > 0 {
		cfg.MaxEvents = *maxEvents
	}
	if *provider != "" {
		cfg.Provider = *provider
	}
	cfg.Defaults()
	if err := cfg.Validate(); err != nil {
		fmt.Fprintf(os.Stderr, "config error: %v\n", err)
		return exitConfig
	}

	// Env fallback for secrets.
	gitlabTokenVal := *gitlabToken
	if gitlabTokenVal == "" {
		gitlabTokenVal = os.Getenv("GITLAB_TOKEN")
	}
	if gitlabTokenVal == "" {
		fmt.Fprintln(os.Stderr, "error: GitLab token not set (use --gitlab-token or GITLAB_TOKEN env)")
		return exitEnv
	}

	gc := gitlab.New(cfg.GitLabHost, gitlabTokenVal, 30*time.Second)

	// Validate the optional GitLab publisher up front so its config
	// errors surface before the (more common) LLM provider check.
	if cfg.Publish.Enabled {
		tokenEnv := cfg.Publish.TokenEnv
		if tokenEnv == "" {
			tokenEnv = "GITLAB_REPORTS_TOKEN"
		}
		if os.Getenv(tokenEnv) == "" {
			fmt.Fprintf(os.Stderr, "error: publish.enabled=true but $%s is not set\n", tokenEnv)
			return exitEnv
		}
		if cfg.Publish.Project == "" {
			fmt.Fprintln(os.Stderr, "error: publish.enabled=true but publish.project is empty")
			return exitConfig
		}
	}

	// Resolve LLM provider and keys.
	var llmProvider llm.Provider
	switch cfg.Provider {
	case "openai":
		key := *openaiKey
		if key == "" {
			key = os.Getenv("OPENAI_API_KEY")
		}
		// Local OpenAI-compatible servers (Ollama, vLLM, LM Studio, llama.cpp)
		// typically don't require auth. Treat an empty key as opt-in to
		// "no auth" when the baseURL points somewhere other than the
		// canonical api.openai.com. For api.openai.com we still require
		// a key — better to fail loud than to silently send empty bearer.
		if key == "" && cfg.OpenAIBaseURL == "https://api.openai.com/v1" {
			fmt.Fprintln(os.Stderr, "error: provider=openai but OPENAI_API_KEY is not set (or set --openai-base-url for a local server)")
			return exitEnv
		}
		llmProvider = llm.NewOpenAI(key, cfg.Model, cfg.OpenAIBaseURL)
	case "anthropic":
		key := *anthropicKey
		if key == "" {
			key = os.Getenv("ANTHROPIC_API_KEY")
		}
		if key == "" {
			fmt.Fprintln(os.Stderr, "error: provider=anthropic but ANTHROPIC_API_KEY is not set")
			return exitEnv
		}
		llmProvider = llm.NewAnthropic(key, cfg.Model, "")
	default:
		fmt.Fprintf(os.Stderr, "error: unknown provider %q\n", cfg.Provider)
		return exitConfig
	}

	// Pick a publisher. Local disk by default; GitLab MR when
	// cfg.Publish.Enabled is true (token env was validated earlier so we
	// can just read it now).
	var pub publisher.Publisher
	if cfg.Publish.Enabled {
		host := cfg.Publish.Host
		if host == "" {
			host = cfg.GitLabHost
		}
		tokenEnv := cfg.Publish.TokenEnv
		if tokenEnv == "" {
			tokenEnv = "GITLAB_REPORTS_TOKEN"
		}
		pub = publisher.NewGitLab(
			host, os.Getenv(tokenEnv), cfg.Publish.Project,
			cfg.Publish.Prefix, cfg.Publish.DefaultBranch, cfg.Publish.SourceBranchPrefix,
		)
	} else {
		pub = publisher.NewLocal(cfg.OutputDir)
	}

	// Safety guard. Disabled by default. When enabled, every LLM call is
	// preceded by a prompt-injection check via the decide API.
	var guard safety.Guard = safety.NoopGuard{}
	safetyOn := *safetyEnabled || cfg.Safety.Enabled
	if safetyOn {
		decisionURL := *safetyURL
		if decisionURL == "" {
			decisionURL = cfg.Safety.DecisionURL
		}
		if decisionURL == "" {
			fmt.Fprintln(os.Stderr, "error: --safety-enabled but no decision URL (set --safety-url or config safety.decision_url)")
			return exitConfig
		}
		tokenEnv := cfg.Safety.DecisionTokenEnv
		if tokenEnv == "" {
			tokenEnv = "SAFETY_DECISION_TOKEN"
		}
		token := *safetyToken
		if token == "" {
			token = os.Getenv(tokenEnv)
		}
		threshold := cfg.Safety.InjectionThreshold
		if threshold <= 0 {
			threshold = 0.7
		}
		guard = safety.NewDecide(decisionURL, token, threshold)
	}

	periodModeParsed, err := run.ParsePeriodMode(*periodMode)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: --period-mode: %v\n", err)
		return exitUsage
	}

	pipe := run.New(cfg, gc, llmProvider, pub, guard, run.Options{
		Projects:             projects,
		DiscoveredGroups:     discoverGroups,
		Since:                cfg.Lookback(),
		Provider:             cfg.Provider,
		Model:                cfg.Model,
		Force:                *force,
		DryRun:               *dryRun,
		IncludeDiffs:         *includeDiffs,
		InternalOnlyProjects: unionSlices(internalOnly, cfg.InternalOnlyProjects),
		PeriodMode:           periodModeParsed,
		DiscoverByTopic:      *discoverTopic,
	})

	ctx, cancel := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer cancel()

	res, err := pipe.Run(ctx)
	printSummary(res, err, *dryRun, cfg.Lookback())
	if err != nil {
		return classify(err)
	}
	return exitOK
}

func printSummary(res run.Result, err error, dryRun bool, window time.Duration) {
	if err == nil && !dryRun {
		var totalEvents, usedEvents int
		for _, p := range res.Projects {
			totalEvents += p.EventsFetched
			usedEvents += p.EventsUsed
		}
		// Count what was actually published, not what a full two-audience
		// run would produce: team-only projects write one file, and the
		// epic rollups are separate.
		fileCount := len(res.RollupFiles) + len(res.EpicRollupFiles)
		for _, p := range res.Projects {
			fileCount += len(p.FilesWritten)
		}
		fmt.Fprintf(os.Stderr, "summarizer: ok — %d project(s), %d event(s) (%d used), %d file(s) written (window=%s)\n",
			len(res.Projects), totalEvents, usedEvents, fileCount, window)
		for _, p := range res.Projects {
			for _, f := range p.FilesWritten {
				fmt.Fprintf(os.Stderr, "  → %s\n", f)
			}
			for aud, u := range p.TokensByAudience {
				fmt.Fprintf(os.Stderr, "  tokens[%s/%s]: prompt=%d completion=%d total=%d\n",
					p.Project, aud, u.PromptTokens, u.CompletionTokens, u.TotalTokens)
			}
		}
		for _, f := range res.RollupFiles {
			fmt.Fprintf(os.Stderr, "  → %s (rollup)\n", f)
		}
		for _, f := range res.EpicRollupFiles {
			fmt.Fprintf(os.Stderr, "  → %s (epics rollup)\n", f)
		}
		for aud, u := range res.TokensByAudience {
			fmt.Fprintf(os.Stderr, "  tokens[rollup/%s]: prompt=%d completion=%d total=%d\n",
				aud, u.PromptTokens, u.CompletionTokens, u.TotalTokens)
		}
		return
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "summarizer: %v\n", err)
	}
}

// classify maps pipeline errors to exit codes. Errors from internal/* packages
// are not necessarily wrapped with a recognizable error type yet, so this is
// a string-match pass. Tighten with typed sentinels if exit-code fidelity
// becomes important.
func classify(err error) int {
	if err == nil {
		return exitOK
	}
	switch {
	case errors.Is(err, run.ErrInjection):
		return exitInjection
	case errors.Is(err, publisher.ErrExists):
		return exitWrite
	}
	msg := err.Error()
	switch {
	case strings.Contains(msg, "fetch "):
		return exitGitLab
	case strings.Contains(msg, "llm "):
		return exitLLM
	case strings.Contains(msg, "write "):
		return exitWrite
	case strings.Contains(msg, "config"):
		return exitConfig
	case strings.Contains(msg, "render"):
		return exitLLM
	}
	return exitUnknown
}

// unionSlices merges two string slices, deduping on exact equality.
// Order: first input first. Used to combine the --internal-only-project
// flag with summarizer.yaml's internal_only_projects block.
func unionSlices(a, b []string) []string {
	out := make([]string, 0, len(a)+len(b))
	seen := make(map[string]bool, len(a)+len(b))
	for _, s := range slices.Concat(a, b) {
		if !seen[s] {
			out = append(out, s)
			seen[s] = true
		}
	}
	return out
}

// stringSliceFlag is a custom flag.Value that accepts both repeated
// invocations (--project X --project Y) and comma-separated values
// (--project X,Y) in a single invocation. Empty entries are dropped so
// "--project X,,Y" doesn't produce an empty string.
//
// stdlib flag (as of Go 1.26) doesn't ship a slice type, and pulling in
// cobra for one flag is overkill. ~15 lines of custom code wins either way.
type stringSliceFlag []string

func (s *stringSliceFlag) String() string {
	return strings.Join(*s, ",")
}

func (s *stringSliceFlag) Set(v string) error {
	for _, p := range strings.Split(v, ",") {
		if p = strings.TrimSpace(p); p != "" {
			*s = append(*s, p)
		}
	}
	return nil
}
